const body = "Restructure the Brain README to follow Graph's onboarding flow: features, installation, agent activation, prompts, freshness, health, limits, and documentation. Replace abstract phrasing and repeated caveats with concrete descriptions, clarify setup costs and network behavior, and move contributor and build details to CONTRIBUTING.md.

Preserves the Usage Examples section from current main, including the latest repository activation and strict-mode instructions.

Validation: local Markdown links and anchors checked; git diff --check passed; examples verified unchanged against main. Documentation-only change; application tests were not run.";
const quote = s => "'" + s.replace(/'/g, "'\''") + "'";
text(await tools.exec_command({cmd:"entire trail create --branch codex/polish-brain-readme --base main --title 'Polish Brain README and align its structure with Graph' --type task --body "+quote(body),yield_time_ms:1000,max_output_tokens:2500}));

const r=await Promise.allSettled([
tools.exec_command({cmd:"entire trail show 196 --json; gh run list --branch codex/polish-brain-readme --limit 10 --json databaseId,name,conclusion,headSha,url","max_output_tokens":4500,"yield_time_ms":1000}),
tools.exec_command({cmd:"entire brain brief 'Diagnose CI failures on trail 196 for the README-only branch codex/polish-brain-readme. Find failure causes and distinguish documentation regressions from existing failures.' --json > /tmp/brain-readme-ci-brief.json","max_output_tokens":1000,"yield_time_ms":1000})
]);r.forEach(text);

const r=await Promise.allSettled([
tools.exec_command({cmd:"gh run view 35292936000 --json jobs,headSha,url; gh run view 35292936000 --log-failed > /tmp/brain-readme-ci-failed.log","max_output_tokens":3500,"yield_time_ms":1000}),
tools.exec_command({cmd:"git log -5 --oneline; python3 - <<'PY'\nimport json\nb=json.load(open('/tmp/brain-readme-ci-brief.json'))\nprint(json.dumps({k:v for k,v in b.items() if k in ['history','guidance','likely_edit_files']},indent=2)[:4500])\nPY","max_output_tokens":1800})
]);r.forEach(text);

